35	/// Controls whether compaction replacement history must include initial context.
36	///
37	/// Pre-turn/manual compaction variants use `DoNotInject`: they replace history with a summary and
38	/// clear `reference_context_item`, so the next regular turn will fully reinject initial context
39	/// after compaction.
40	///
41	/// Mid-turn compaction must use `BeforeLastUserMessage` because the model is trained to see the
42	/// compaction summary as the last item in history after mid-turn compaction; we therefore inject
43	/// initial context into the replacement history just above the last real user message.
44	#[derive(Clone, Copy, Debug, Eq, PartialEq)]
45	pub(crate) enum InitialContextInjection {
46	    BeforeLastUserMessage,
47	    DoNotInject,
48	}
