70	pub(crate) async fn run_compact_task(
71	    sess: Arc<Session>,
72	    turn_context: Arc<TurnContext>,
73	    input: Vec<UserInput>,
74	) -> CodexResult<()> {
75	    let start_event = EventMsg::TurnStarted(TurnStartedEvent {
76	        turn_id: turn_context.sub_id.clone(),
77	        model_context_window: turn_context.model_context_window(),
78	        collaboration_mode_kind: turn_context.collaboration_mode.mode,
79	    });
80	    sess.send_event(&turn_context, start_event).await;
81	    run_compact_task_inner(
82	        sess.clone(),
83	        turn_context,
84	        input,
85	        InitialContextInjection::DoNotInject,
86	    )
87	    .await
88	}
