90	async fn run_compact_task_inner(
91	    sess: Arc<Session>,
92	    turn_context: Arc<TurnContext>,
93	    input: Vec<UserInput>,
94	    initial_context_injection: InitialContextInjection,
95	) -> CodexResult<()> {
96	    let compaction_item = TurnItem::ContextCompaction(ContextCompactionItem::new());
97	    sess.emit_turn_item_started(&turn_context, &compaction_item)
98	        .await;
99	    let initial_input_for_turn: ResponseInputItem = ResponseInputItem::from(input);
100	
101	    let mut history = sess.clone_history().await;
102	    history.record_items(
103	        &[initial_input_for_turn.into()],
104	        turn_context.truncation_policy,
105	    );
106	
107	    let mut truncated_count = 0usize;
108	
109	    let max_retries = turn_context.provider.stream_max_retries();
110	    let mut retries = 0;
111	    let mut client_session = sess.services.model_client.new_session();
112	    // Reuse one client session so turn-scoped state (sticky routing, websocket incremental
113	    // request tracking)
114	    // survives retries within this compact turn.
115	
116	    loop {
117	        // Clone is required because of the loop
118	        let turn_input = history
119	            .clone()
120	            .for_prompt(&turn_context.model_info.input_modalities);
121	        let turn_input_len = turn_input.len();
122	        let prompt = Prompt {
123	            input: turn_input,
124	            base_instructions: sess.get_base_instructions().await,
125	            personality: turn_context.personality,
126	            ..Default::default()
127	        };
128	        let turn_metadata_header = turn_context.turn_metadata_state.current_header_value();
129	        let attempt_result = drain_to_completed(
130	            &sess,
131	            turn_context.as_ref(),
132	            &mut client_session,
133	            turn_metadata_header.as_deref(),
134	            &prompt,
135	        )
136	        .await;
137	
138	        match attempt_result {
139	            Ok(()) => {
140	                if truncated_count > 0 {
141	                    sess.notify_background_event(
142	                        turn_context.as_ref(),
143	                        format!(
144	                            "Trimmed {truncated_count} older thread item(s) before compacting so the prompt fits the model context window."
145	                        ),
146	                    )
147	                    .await;
148	                }
149	                break;
150	            }
151	            Err(CodexErr::Interrupted) => {
152	                return Err(CodexErr::Interrupted);
153	            }
154	            Err(e @ CodexErr::ContextWindowExceeded) => {
155	                if turn_input_len > 1 {
156	                    // Trim from the beginning to preserve cache (prefix-based) and keep recent messages intact.
157	                    error!(
158	                        "Context window exceeded while compacting; removing oldest history item. Error: {e}"
159	                    );
160	                    history.remove_first_item();
161	                    truncated_count += 1;
162	                    retries = 0;
163	                    continue;
164	                }
165	                sess.set_total_tokens_full(turn_context.as_ref()).await;
166	                let event = EventMsg::Error(e.to_error_event(None));
167	                sess.send_event(&turn_context, event).await;
168	                return Err(e);
169	            }
170	            Err(e) => {
171	                if retries < max_retries {
172	                    retries += 1;
173	                    let delay = backoff(retries);
174	                    sess.notify_stream_error(
175	                        turn_context.as_ref(),
176	                        format!("Reconnecting... {retries}/{max_retries}"),
177	                        e,
178	                    )
179	                    .await;
180	                    tokio::time::sleep(delay).await;
181	                    continue;
182	                } else {
183	                    let event = EventMsg::Error(e.to_error_event(None));
184	                    sess.send_event(&turn_context, event).await;
185	                    return Err(e);
186	                }
187	            }
